import { ChangeDetectionStrategy, Component, HostListener, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { NavbarComponent } from './navbar/navbar.component';
import { AboutComponent } from './about/about.component';
import { TeamComponent } from './team/team.component';
import { MenuComponent } from './menu/menu.component';
import { CardCarouselComponent } from './card-carousel/card-carousel.component';
import { BookingFormComponent } from './booking-form/booking-form.component';
import { FooterComponent } from './footer/footer.component';
import { ScrollService } from './services/scroll.service';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [
    CommonModule,
    NavbarComponent,
    AboutComponent,
    TeamComponent,
    MenuComponent,
    CardCarouselComponent,
    BookingFormComponent,
    FooterComponent,
  ],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AppComponent {
  private scrollService = inject(ScrollService);
  private ticking = false;

  hasScrolledPastHome = false;

  @HostListener('window:scroll')
  onScroll(): void {
    if (this.ticking) return;
    this.ticking = true;
    requestAnimationFrame(() => {
      this.hasScrolledPastHome = window.scrollY > window.innerHeight - 750;
      this.ticking = false;
    });
  }

  scrollToBookingTable(): void {
    this.scrollService.scrollTo('booking-table');
  }

  scrollToTop(event: Event): void {
    event.preventDefault();
    this.scrollService.scrollTo('home');
  }

  galleryImages = [
    'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=800',
    'https://images.unsplash.com/photo-1552566626-52f8b828add9?w=800',
    'https://images.unsplash.com/photo-1600891964092-4316c288032e?w=800',
    'https://images.unsplash.com/photo-1559339352-11d035aa65de?w=800',
    'https://images.unsplash.com/photo-1592861956120-e524fc739696?w=800',
    'https://images.unsplash.com/photo-1551218808-94e220e084d2?w=800',
  ];
}
